// Golden values of the Projects map screen (docs/spec/03 §3): the DAL (seeded in-memory database) + view model
// reproduce the prototype's worldmap render values in EN and FR for every zone — KPI tiles, breadcrumb, "Sites"
// list (groups, rows, tags) and the map payload (points, labels, zone frame). worldmap.golden.json was generated by
// scripts/proto-golden-worldmap.ts (prototype logic in node:vm, `renderVals`, director). Deliberate deviations are
// asserted explicitly: project names translated on their own (the prototype left "ERP Migration — Phase 2" and
// every tooltip name and client in English), marker and tooltip tags from codes (in French the prototype compared
// translated health labels), singular "1 project located".
import { beforeAll, describe, expect, it, vi } from 'vitest';
vi.mock('next/navigation', () => ({ usePathname: () => '/portfolio/map', useRouter: () => ({ push() {}, prefetch() {}, refresh() {} }) }));
import { createElement as h } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { crumbBase } from '@/components/app/shell/nav-model';
import { I18nProvider } from '@/i18n/client';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import { getProjectsMap } from '@/server/dal/geo';
import type { ZoneCode } from '@/server/db/codes';
import { geoNaturalEarth1 } from 'd3-geo';
import { clusterPoints, markerLabelText, tooltipTitle } from '@/domain/worldmap';
import { buildWorldMapModel, openHref, type WorldMapModel } from './model';
import { WorldMapBody } from './worldmap-body';
import golden from './worldmap.golden.json';
import { HEALTH_LABEL, HEALTH_TAG } from '@/domain/health';
import { D7_HEALTH, withD7Health } from '@/test/d7-cost-control';

/* eslint-disable @typescript-eslint/no-explicit-any */
// Delivery 7 (R-073, C-2a): the health of the six projects with activities follows their computed progress, actual cost and SPI
// (HLT-026 off track, NDC-031 / RCF-019 at risk, MSR-012 on track): list rows, points and tooltip tags; "At risk" tile per zone.
const HEALTH_FR: Record<string, string> = { 'On track': 'Conforme', 'At risk': 'À risque', 'Off track': 'Hors trajectoire' };
const tipTags = (tips: Record<string, any[]>) =>
  Object.fromEntries(Object.entries(tips).map(([key, clusters]) => [key, clusters.map((c) => ({
    ...c,
    rows: c.rows.map((r: any) => {
      const now = D7_HEALTH[r.sub.split(' · ')[0]];
      if (!now || r.tags.length < 2) return r;
      const label = key.startsWith('fr|') ? HEALTH_FR[HEALTH_LABEL[now]] : HEALTH_LABEL[now];
      // The status tag of an active project takes the tone of its health (the map's tooltip colouring).
      return { ...r, tags: [`${HEALTH_TAG[now]}|${r.tags[0].split('|')[1]}`, `${HEALTH_TAG[now]}|${label}`] };
    }),
  }))]));
const D7_AT_RISK: Record<string, [string, string]> = { euna: ['2', 'var(--color-accent-300)'], afr: ['1', 'var(--color-accent-300)'] };
const patched = withD7Health(golden) as any;
const G = {
  ...patched,
  ...Object.fromEntries(Object.entries(patched).filter(([k]) => k.includes('|')).map(([k, v]: [string, any]) => {
    const zone = k.split('|')[1];
    const fix = D7_AT_RISK[zone];
    return [k, fix ? { ...v, kpis: v.kpis.map((x: any, i: number) => (i === 3 ? { ...x, value: fix[0], color: fix[1] } : x)) } : v];
  })),
  tips: tipTags(patched.tips),
};
const ZONES = [null, 'euna', 'afr', 'apac'] as const;
const LANGS: Lang[] = ['en', 'fr'];
const text = (html: string) => html.replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;/g, '’').replace(/\s+/g, ' ');
const TONE_CLASS = (tone: string) => `tag tag-${tone}`;
/** Prototype FR names the rebuild translates on their own (Delivery 1 deviation, `projectName`). */
const FR_NAME_FIX: Record<string, string> = { '#032 · ERP Migration — Phase 2': '#032 · Migration ERP — Phase 2' };

const models = new Map<string, WorldMapModel>();
const modelOf = (lang: Lang, zone: ZoneCode | null) => models.get(`${lang}|${zone}`)!;

beforeAll(async () => {
  setDb(await openDatabase());
  for (const lang of LANGS) for (const zone of ZONES) models.set(`${lang}|${zone}`, buildWorldMapModel(await getProjectsMap(zone), makeT(lang), lang));
}, 60_000);

describe('projects map — view model vs prototype', () => {
  for (const lang of LANGS)
    for (const zone of ZONES) {
      const g = G[`${lang}|${zone}`];
      it(`${lang} · zone ${zone}: KPI tiles, crumb, site groups and rows`, () => {
        const m = modelOf(lang, zone);
        const t = makeT(lang);
        expect(m.kpis.map((k) => [k.label, k.value, k.sub, k.alert ? 'var(--color-accent-300)' : 'var(--color-text)'])).toEqual(
          g.kpis.map((k: any) => [k.label, String(k.value), k.sub, k.color]),
        );
        expect(t(crumbBase('worldmap') + ' · ' + m.crumbExtra)).toBe(g.crumb);
        expect(m.siteCount).toBe(g.siteCount);
        expect(m.zoneEmpty).toBe(g.zoneEmpty);
        expect(m.groups.map((x) => ({ city: x.city, country: x.country, count: x.count }))).toEqual(g.groups.map((x: any) => ({ city: x.city, country: x.country, count: x.count })));
        expect(m.groups.map((x) => x.focusCode)).toEqual(g.groups.map((x: any) => x.items[0].code));
        expect(
          m.groups.flatMap((x) =>
            x.items.map((i) => ({ code: i.code, name: i.name, sub: i.sub, status: i.status.label, statusClass: TONE_CLASS(i.status.tone), health: i.health?.label ?? '', healthClass: i.health ? TONE_CLASS(i.health.tone) : 'tag tag-neutral' })),
          ),
        ).toEqual(g.groups.flatMap((x: any) => x.items.map((i: any) => ({ ...i, name: (lang === 'fr' && FR_NAME_FIX[i.name]) || i.name }))));
      });

      it(`${lang} · zone ${zone}: map points, labels and zone frame`, () => {
        const m = modelOf(lang, zone);
        const t = makeT(lang);
        // Places, coordinates, categories and the translated country / health / status the map received.
        expect(m.points.map((p) => ({ code: p.code, city: p.city, country: p.country, lat: p.lat, lng: p.lng, cat: p.category, health: p.health?.label ?? '', status: p.status.label, pm: p.sub.split(' · ')[1] }))).toEqual(
          g.points.map((p: any) => ({ code: p.code, city: p.city, country: p.country, lat: p.lat, lng: p.lng, cat: p.cat, health: p.health, status: p.status, pm: p.pm })),
        );
        // The tooltip translates names and clients like the list (the prototype sent them in English).
        expect(m.points.map((p) => [p.name, p.sub])).toEqual(g.points.map((p: any) => [`${p.name.split(' · ')[0]} · ${t(p.name.slice(p.name.indexOf(' · ') + 3))}`, `${p.code} · ${p.pm} · ${t(p.client)}`]));
        const ui = g.ui;
        expect([m.labels.world, m.labels.fit, m.labels.ontrack, m.labels.risk, m.labels.pipeline, m.labels.closed, m.labels.open, m.labels.loading, m.labels.failed]).toEqual(
          [ui.world, ui.fit, ui.ontrack, ui.risk, ui.pipeline, ui.closed, ui.open, ui.loading, ui.failed],
        );
        // The second view button shows the zone name when a zone is selected (map `buildCtl`).
        expect(m.labels.europe).toBe(g.zone ? g.zone.label : ui.europe);
        expect(m.zone ? { label: m.zone.label, bounds: m.zone.bounds } : null).toEqual(g.zone);
      });
    }

  it('marker styles and tooltip tags come from codes, so French matches English', () => {
    const en = modelOf('en', null);
    const fr = modelOf('fr', null);
    expect(fr.points.map((p) => [p.style, p.status.tone, p.health?.tone ?? null])).toEqual(en.points.map((p) => [p.style, p.status.tone, p.health?.tone ?? null]));
    // R-073: NDC-031 is at risk (SPI 0.96 computed from its activities and BL1; the prototype's synthetic figures had it on track).
    expect(Object.fromEntries(en.points.map((p) => [p.code, p.style]))).toMatchObject({ 'HLT-026': 'risk', 'NDC-031': 'risk', 'RCF-019': 'risk', 'WSA-044': 'pipeline', 'DRR-009': 'closed' });
  });

  it('a project opens its Plan when it has planning data, else the Projects register searched by its code', () => {
    const m = modelOf('en', null);
    const href = Object.fromEntries(m.points.map((p) => [p.code, p.href]));
    for (const code of ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012']) expect(href[code]).toBe(`/projects/${code}/plan`);
    for (const code of ['EWA-051', 'PRS-038', 'DRR-009', 'TTR-017']) expect(href[code]).toBe(`/portfolio/projects?q=${code}`);
    expect(m.groups.flatMap((g) => g.items.map((i) => i.href))).toEqual(m.groups.flatMap((g) => g.items.map((i) => href[i.code])));
    expect(openHref({ code: 'A B', hasData: false })).toBe('/portfolio/projects?q=A%20B');
  });
});

describe('projects map — tooltip and marker texts vs the prototype map page (showTip)', () => {
  // Prototype tooltips for every cluster of an 800 × 500 frame at k = 1, 2.4, 6, 48 (`tips` in the golden).
  // Deliberate deviations: names and clients translated in French (the prototype sent them in English), and tag
  // tones from codes, so French tags carry the English classes (the prototype compared translated health labels).
  const proj = geoNaturalEarth1().fitExtent([[6, 6], [794, 494]], { type: 'Sphere' });
  for (const lang of LANGS)
    for (const zone of ZONES)
      for (const k of [1, 2.4, 6, 48]) {
        it(`${lang} · zone ${zone} · k=${k}`, () => {
          const m = modelOf(lang, zone);
          const t = makeT(lang);
          const placed = m.points.map((p) => {
            const [x, y] = proj([p.lng, p.lat])!;
            return { ...p, x, y };
          });
          const g = G.tips[`${lang}|${zone}|${k}`];
          const en = G.tips[`en|${zone}|${k}`];
          const fixName = (n: string) => (lang === 'fr' ? `${n.split(' · ')[0]} · ${t(n.slice(n.indexOf(' · ') + 3))}` : n);
          const fixSub = (sub: string) => (lang === 'fr' ? sub.split(' · ').map((x, i) => (i === 2 ? t(x) : x)).join(' · ') : sub);
          expect(
            clusterPoints(placed, k).map((c) => ({
              codes: c.items.map((i) => i.code),
              header: tooltipTitle(c.items, t),
              rows: c.items.map((i) => ({
                name: i.name, sub: i.sub,
                tags: [i.status, ...(i.health ? [i.health] : [])].map((x) => `tag tag-${x.tone}|${x.label}`),
              })),
              open: `${m.labels.open} →`,
              label: markerLabelText(c.items, t),
            })),
          ).toEqual(
            g.map((c: any, ci: number) => ({
              ...c,
              rows: c.rows.map((r: any, ri: number) => ({
                name: fixName(r.name), sub: fixSub(r.sub),
                tags: r.tags.map((x: string, ti: number) => `${en[ci].rows[ri].tags[ti].split('|')[0]}|${x.split('|')[1]}`),
              })),
            })),
          );
        });
      }
});

describe('projects map — static render', () => {
  it('French body: tiles, list, map controls, legend, loading state and links', () => {
    const t = makeT('fr');
    const html = renderToStaticMarkup(h(I18nProvider, { lang: 'fr', children: h(WorldMapBody, { model: modelOf('fr', null), t }) }));
    const txt = text(html);
    for (const s of [
      'Projets localisés', 'Tout le portefeuille', '6 pays', 'Actifs', '5 en pipeline', 'À risque', '1 hors trajectoire', 'Sites · 11',
      'Le Havre', 'France · 3', 'Maroc · 1', '#026 · Extension du terminal Harbor Line', 'HLT-026 · R. Aubert · Autorité portuaire',
      'Fabrication & Assemblage', 'Mise en service & SAT', 'Études', 'Hors trajectoire', 'Conforme', 'Monde', 'Europe', 'Projets',
      'À risque / hors trajectoire', 'Clos / en attente', 'Natural Earth · world-atlas 2.0.2', 'Chargement de la géométrie de la carte…',
      'Déplacez et zoomez · cliquez un repère pour ouvrir le projet · survolez un projet pour le mettre en évidence sur la carte',
    ])
      expect(txt).toContain(s);
    expect(html).toContain('aria-label="Mappemonde des projets"');
    expect(html).toContain('aria-label="Légende de la carte"');
    expect(html).toContain('href="/projects/HLT-026/plan"');
    expect(html).toContain('href="/portfolio/projects?q=PRS-038"');
    expect(txt).not.toContain('Aucun projet dans cette zone');
    // 17 located projects at the initial (world) zoom: 7 markers, two of them clusters (France 10, Morocco 2).
    expect(html.match(/<text class="[^"]*count/g)?.length).toBe(2);
  });

  it('English body with a zone: zone button label and empty-zone notice', () => {
    const t = makeT('en');
    const m = { ...modelOf('en', 'afr'), groups: [], points: [], siteCount: 0, zoneEmpty: true };
    const txt = text(renderToStaticMarkup(h(I18nProvider, { lang: 'en', children: h(WorldMapBody, { model: m, t }) })));
    expect(txt).toContain('Sites · 0');
    expect(txt).toContain('No project in this zone for this view');
    expect(txt).toContain('World Africa Projects');
    expect(txt).toContain('Loading map geometry…');
  });
});
